      "b2b.hero.eyebrow": "DECENTRALIZED & SOVEREIGN",
      "b2b.hero": "<span class=\"neon\">Decentralized.</span><br>Sovereign.",
      "b2b.hero.sub": "You govern the AI you use. Vote on what it does. Influence decisions at the protocol — not through a corporation.",
      "b2b.hero.cta1": "Run a miner →",
