      "b2b.trust.1t": "Influence decisions",
      "b2b.trust.1d": "Every node has a voice. Shape what the network runs — models, skills, and rules — through the protocol, not a boardroom.",
      "b2b.trust.2t": "Decentralized by design",
      "b2b.trust.2d": "Independent nodes, peer-to-peer. No corporation owns the mesh. No central switch to flip.",
      "b2b.trust.3t": "Sovereign control",
