      "fw.hero.sub": "White-label, sovereign <span class=\"text-[#171717]\">AI compute</span> stablecoins",
      "fw.fund.eyebrow": "RESERVE FUNDING",
      "fw.fund.title": "Seeded by an <span class=\"neon\">offshore note.</span>",
      "fw.fund.desc": "Each coin's reserve can be seeded with privately placed notes: an offshore SPV places them with qualified international investors, 100% of the proceeds sit in a ring-fenced custodial reserve backing the coin, and the notes are serviced by compute revenue plus yield on the reserve. Coin holders never carry investor risk.",
      "fw.fund.notice": "A structure, not an offer — available to qualified institutional investors on request.",
      "mnr.nav.daicoin": "DAI coin",
      "mnr.hero.title": "Power the AI Brain.<br><span class=\"neon\">It earns when you are out.</span>",
      "mnr.hero.cta1": "Start running a node",
      "mnr.hero.cta2": "See the live mesh",
      "mnr.net.eyebrow": "THE INFRASTRUCTURE",
      "mnr.net.title": "A living mesh of<br>compute providers.",
      "mnr.net.desc": "Nodes running local LLMs form a decentralized AI compute network. When tasks arrive, your machine processes them and earns — no data center required.",
      "mnr.app.eyebrow": "THE DESKTOP APP",
      "mnr.app.desc": "One native app. Your node joins the network, your local LLM solves incoming AI tasks, and you earn DAI each time.",
      "mnr.dl.title": "Ready to contribute real compute?",
      "mnr.dl.desc": "Download the pre-built binary for your system. Double-click to install — no terminal, no coding required for non-technical users.",
      "mnr.dl.linux.os": "Ubuntu • Debian • Fedora • Any distro",
      "mnr.dl.linux.desc": "Portable AppImage — one file, runs on any distro. Download → chmod +x → double-click or run from anywhere. No root install.",
