      "fw.hero.sub": "White-label суверенные стейблкоины для <span class=\"text-[#171717]\">ИИ-вычислений</span>",
      "fw.fund.eyebrow": "ФИНАНСИРОВАНИЕ РЕЗЕРВА",
      "fw.fund.title": "Старт — через <span class=\"neon\">офшорную ноту.</span>",
      "fw.fund.desc": "Резерв каждой монеты может быть сформирован частно размещаемыми нотами: офшорная SPV размещает их среди квалифицированных международных инвесторов, 100% средств лежат в обособленном кастодиальном резерве, обеспечивающем монету, а ноты обслуживаются выручкой от вычислений и доходом на самом резерве. Держатели монеты никогда не несут риск инвестора.",
      "fw.fund.notice": "Это структура, а не предложение — доступно квалифицированным институциональным инвесторам по запросу.",
      "mnr.nav.daicoin": "Монета DAI",
