      "exp.recenttx": "Акыркы транзакциялар",
      "fw.hero.sub": "White-label, эгемен стейблкоиндер <span class=\"text-[#171717]\">AI эсептөө</span> үчүн",
      "fw.fund.eyebrow": "РЕЗЕРВДИ КАРЖЫЛОО",
      "fw.fund.title": "Башаты — <span class=\"neon\">офшордук нота.</span>",
      "fw.fund.desc": "Ар бир монетанын резерви жеке жайгаштырылган ноталар менен түзүлүшү мүмкүн: офшордук SPV аларды квалификациялуу эл аралык инвесторлорго жайгаштырат, каражаттын 100% монетаны камсыздаган өзүнчө кастодиалдык резервде сакталат, ал эми ноталар эсептөө кирешеси жана резервдин кирешеси менен тейленет. Монета ээлери инвестордун тобокелин эч качан көтөрбөйт.",
      "fw.fund.notice": "Бул сунуш эмес, структура — квалификациялуу институционалдык инвесторлорго суроо-талап боюнча жеткиликтүү.",
      "mnr.nav.daicoin": "DAI монета",
      "mnr.hero.title": "AI мээни иштет.<br><span class=\"neon\">Сен жокто ал таап турат.</span>",
      "mnr.hero.cta1": "Түйүн иштетүүнү башта",
      "mnr.hero.cta2": "Жандуу тармакты көр",
      "mnr.net.eyebrow": "ИНФРАСТРУКТУРА",
      "mnr.net.title": "Эсептөө камсыздоочуларынын<br>жандуу тармагы.",
      "mnr.net.desc": "Локалдык LLM менен иштеген түйүндөр борборсуздандырылган AI эсептөө тармагын түзөт. Тапшырмалар келгенде, сенин машинаң аларды иштетип, таап турат — маалымат борбору кереги жок.",
      "mnr.app.eyebrow": "ДЕСКТОП КОЛДОНМО",
      "mnr.app.desc": "Бир нативдик колдонмо. Түйүнүң тармакка кошулат, локалдык LLM кирген AI тапшырмаларын чечет, ар бир жолу сен DAI табасың.",
      "mnr.dl.title": "Чыныгы эсептөө кошууга даярсыңбы?",
      "mnr.dl.desc": "Системаң үчүн даяр бинардык файлды жүктө. Орнотуу үчүн кош чык — техникалык эмес колдонуучуларга терминал да, код да кереги жок.",
      "mnr.dl.linux.os": "Ubuntu • Debian • Fedora • Каалаган дистрибутив",
      "mnr.dl.linux.desc": "Портативдик AppImage — бир файл, каалаган дистрибутивде иштейт. Жүктө → chmod +x → кош чык же каалаган жерден иштет. Root менен орнотуу кереги жок.",
      "mnr.dl.linux.btn1": "AppImage жүктөө (x64)",
      "mnr.dl.linux.btn2": "AppImage жүктөө (ARM64)",
      "mnr.dl.mac.desc": "Ач .dmg → Applications ичине сүйрө • Security & Privacy бөлүмүндө «Open Anyway» керек болушу мүмкүн",
      "mnr.dl.mac.btn1": "Apple Silicon .dmg жүктөө",
