      "mnr.dl.win.desc": "Стандарттуу .exe орнотуучу жарлыктар, Start Menu жазуусу жана таза чыгаруучу менен. NSIS менен курулган.",
      "mnr.dl.win.btn": "Windows орнотуучусун жүктөө",
