      "exp.recenttx": "最近交易",
      "fw.hero.sub": "白標、主權嘅<span class=\"text-[#171717]\">AI 算力</span>穩定幣",
      "fw.fund.eyebrow": "儲備融資",
      "fw.fund.title": "由一張<span class=\"neon\">離岸票據</span>啟動。",
