      "fw.hero.sub": "Stablecoins white-label y soberanas de <span class=\"text-[#171717]\">cómputo IA</span>",
      "fw.fund.eyebrow": "FINANCIACIÓN DE LA RESERVA",
      "fw.fund.title": "Sembrada con una <span class=\"neon\">nota offshore.</span>",
      "fw.fund.desc": "La reserva de cada moneda puede sembrarse con notas colocadas de forma privada: una SPV offshore las coloca entre inversores internacionales cualificados, el 100% de lo recaudado permanece en una reserva segregada en custodia que respalda la moneda, y las notas se atienden con los ingresos de cómputo más el rendimiento de la propia reserva. Los tenedores de la moneda nunca cargan con el riesgo del inversor.",
      "fw.fund.notice": "Una estructura, no una oferta — disponible bajo petición para inversores institucionales cualificados.",
      "mnr.nav.daicoin": "Moneda DAI",
