      "mnr.net.desc": "Los nodos que ejecutan LLM locales forman una red de cómputo IA descentralizada. Cuando llegan tareas, tu máquina las procesa y gana — sin centro de datos.",
      "mnr.app.eyebrow": "LA APP DE ESCRITORIO",
      "mnr.app.desc": "Una sola app nativa. Tu nodo se une a la red, tu LLM local resuelve las tareas de IA entrantes y ganas DAI cada vez.",
