      "fw.hero.sub": "White-Label, souveräne Stablecoins für <span class=\"text-[#171717]\">KI-Rechenleistung</span>",
      "fw.fund.eyebrow": "RESERVE-FINANZIERUNG",
      "fw.fund.title": "Angeschoben durch eine <span class=\"neon\">Offshore-Note.</span>",
      "fw.fund.desc": "Die Reserve jeder Münze kann über privat platzierte Notes aufgebaut werden: Eine Offshore-SPV platziert sie bei qualifizierten internationalen Investoren, 100% der Erlöse liegen in einer abgeschotteten Verwahr-Reserve, die die Münze deckt, und die Notes werden aus Compute-Erlösen plus Zinsen auf die Reserve bedient. Münzinhaber tragen nie das Investorenrisiko.",
      "fw.fund.notice": "Eine Struktur, kein Angebot — auf Anfrage für qualifizierte institutionelle Investoren.",
      "mnr.nav.daicoin": "DAI-Coin",
      "mnr.hero.title": "Treibe das KI-Gehirn an.<br><span class=\"neon\">Es verdient, wenn du weg bist.</span>",
      "mnr.hero.cta1": "Node starten",
      "mnr.hero.cta2": "Live-Mesh ansehen",
      "mnr.net.eyebrow": "DIE INFRASTRUKTUR",
      "mnr.net.title": "Ein lebendiges Mesh aus<br>Compute-Anbietern.",
      "mnr.net.desc": "Nodes mit lokalen LLMs bilden ein dezentrales KI-Rechennetzwerk. Wenn Aufgaben eintreffen, verarbeitet deine Maschine sie und verdient — kein Rechenzentrum nötig.",
      "mnr.app.eyebrow": "DIE DESKTOP-APP",
      "mnr.app.desc": "Eine native App. Dein Node tritt dem Netzwerk bei, dein lokales LLM löst eingehende KI-Aufgaben, und du verdienst jedes Mal DAI.",
      "mnr.dl.title": "Bereit, echte Rechenleistung beizusteuern?",
      "mnr.dl.desc": "Lade die vorgefertigte Binärdatei für dein System herunter. Doppelklick zur Installation — kein Terminal, kein Code für nicht-technische Nutzer.",
      "mnr.dl.linux.os": "Ubuntu • Debian • Fedora • Jede Distro",
      "mnr.dl.linux.desc": "Portables AppImage — eine Datei, läuft auf jeder Distro. Herunterladen → chmod +x → Doppelklick oder von überall starten. Keine Root-Installation.",
      "mnr.dl.linux.btn1": "AppImage herunterladen (x64)",
      "mnr.dl.linux.btn2": "AppImage herunterladen (ARM64)",
      "mnr.dl.mac.desc": "Öffne .dmg → in Applications ziehen • ggf. „Open Anyway“ in Security & Privacy nötig",
      "mnr.dl.mac.btn1": "Apple Silicon .dmg herunterladen",
      "mnr.dl.mac.btn2": "Intel .dmg-Installer herunterladen",
