      "b2b.trust.eyebrow": "حوكمة لا حرّاس أبواب",
      "b2b.trust.title": "أنت توجّه ما يفعله الذكاء الاصطناعي.",
      "b2b.trust.1t": "أثّر في القرارات",
      "b2b.trust.1d": "لكل عقدة صوت. شكّل ما تشغّله الشبكة — النماذج والمهارات والقواعد — عبر البروتوكول لا عبر مجلس إدارة.",
      "b2b.trust.2t": "لامركزي بالتصميم",
      "b2b.trust.2d": "عقد مستقلة، ندّ لندّ. لا تملك أي شركة الشبكة. لا مفتاح مركزي لإطفائها.",
      "b2b.trust.3t": "سيطرة سيادية",
      "b2b.trust.3d": "تختار النماذج والمهارات والبيانات. المفاتيح تبقى لديك. الشروط تضعها أنت.",
      "b2b.trust.4t": "اربح من مساهمتك",
