      "b2b.build.1t": "نماذجك أنت",
      "b2b.build.1d": "أحضر نموذجاً مخصّصاً أو اختر لكل مهمة. اربط مجموعات بيانات خاصة أو اسحب من Hugging Face — الشبكة تشغّله حيث تقول.",
      "b2b.build.2t": "وكلاء ومهارات",
      "b2b.build.2d": "استضف بياناتك ومجموعاتك ومعرفتك. وصّل الأدوات عبر MCP. أنت تقرر ما تراه نُسخك.",
      "b2b.build.3t": "واجهة برمجية واحدة بسيطة",
      "b2b.build.3d": "كل شيء واجهة HTTP واحدة — مهام ودردشة وبحث ومدفوعات. ادمج في فترة بعد ظهر.",
      "b2b.build.3cta": "اقرأ توثيق الواجهة →",
