      "b2b.build.4d": "يُقاس لكل رمز حوسبة ذكاء اصطناعي وبميزانية صارمة لكل مهمة. الميزانية غير المستخدمة تُرد — لا وحدات رسومية خاملة في فاتورتك.",
      "b2b.how.eyebrow": "كيف يعمل",
      "b2b.how.title": "ندّ لندّ، من القاعدة إلى القمة.",
      "b2b.how.1t": "اطلب عملاً",
      "b2b.how.1d": "انشر مهمة على الشبكة بميزانيتك وما تحتاجه: نموذج أو مهارة أو مزيج.",
      "b2b.how.2t": "العُقد تتنافس",
      "b2b.how.2d": "عقد مستقلة بمهارات مطابقة تقدّم وتنفّذ. الأسرع يفوز؛ تدفع فقط ما استُخدم.",
      "b2b.how.3t": "تسوية على السلسلة",
      "b2b.how.3d": "يُوثَّق العمل على السلسلة. تُدفع للعقد مباشرة. بلا وسيط، شفافية كاملة.",
      "b2b.ent.eyebrow": "المؤسسات",
      "b2b.ent.title": "تحتاج نطاقاً<br><span class=\"neon\">أو اتفاقية مستوى خدمة؟</span>",
      "b2b.ent.desc": "سعة مخصّصة وعناقيد خاصة وأسعار حجم لأعباء الإنتاج. تدفع باليورو أو الدولار أو USDT — رسمياً وبفاتورة كاملة — بينما يُدفع لمجتمع تشغيل الشبكة بالعملات المستقرة المحلية.",
      "b2b.ent.cta": "تحدث معنا — احصل على سعر ثابت →",
