      "fw.fund.desc": "يمكن تمويل احتياطي كل عملة بسندات موضوعة بشكل خاص: تضعها شركة ذات غرض خاص خارجية لدى مستثمرين دوليين مؤهلين، و100٪ من العائدات تبقى في احتياطي حفظ معزول يدعم العملة، وتُخدم السندات من إيرادات الحوسبة وعائد الاحتياطي. حاملو العملة لا يتحملون أبداً مخاطر المستثمر.",
