      "exp.recenttx": "تراکنش‌های اخیر",
      "fw.hero.sub": "استیبل‌کوین‌های حاکمیتی و وایت‌لیبل برای <span class=\"text-[#171717]\">محاسبه هوش مصنوعی</span>",
      "fw.fund.eyebrow": "تأمین ذخیره",
      "fw.fund.title": "با یک <span class=\"neon\">نوشتار فراساحلی</span> بذر می‌خورد.",
      "fw.fund.desc": "ذخیره هر سکه می‌تواند با نوشتارهای خصوصی بذر شود: یک SPV فراساحلی آن‌ها را نزد سرمایه‌گذاران بین‌المللی واجد شرایط می‌گذارد، ۱۰۰٪ عواید در ذخیره حضانت جداگانه پشتوانه سکه می‌ماند، و نوشتارها از درآمد محاسبه به‌علاوه بازده ذخیره سرویس می‌شوند. دارندگان سکه هرگز ریسک سرمایه‌گذار را حمل نمی‌کنند.",
      "fw.fund.notice": "ساختار است، نه پیشنهاد — بنا به درخواست برای سرمایه‌گذاران نهادی واجد شرایط.",
      "mnr.nav.daicoin": "سکه DAI",
      "mnr.hero.title": "مغز هوش مصنوعی را تغذیه کن.<br><span class=\"neon\">وقتی بیرون هستی درآمد می‌گیرد.</span>",
      "mnr.hero.cta1": "شروع اجرای گره",
      "mnr.hero.cta2": "شبکه زنده را ببین",
      "mnr.net.eyebrow": "زیرساخت",
      "mnr.net.title": "شبکه زنده‌ای از<br>تأمین‌کنندگان محاسبه.",
      "mnr.net.desc": "گره‌هایی که مدل زبانی محلی اجرا می‌کنند شبکه محاسبه غیرمتمرکز هوش مصنوعی می‌سازند. وقتی کار می‌رسد دستگاهت پردازش می‌کند و درآمد می‌گیرد — بدون مرکز داده.",
      "mnr.app.eyebrow": "برنامه رومیزی",
      "mnr.app.desc": "یک برنامه بومی. گره‌ات به شبکه می‌پیوندد، مدل محلی وظایف ورودی هوش مصنوعی را حل می‌کند، و هر بار DAI می‌گیری.",
      "mnr.dl.title": "آماده مشارکت محاسبه واقعی هستی؟",
      "mnr.dl.desc": "باینری ازپیش‌ساخته سیستم خود را دانلود کن. برای نصب دوبار کلیک — بدون ترمینال و کدنویسی برای کاربران غیرفنی.",
      "mnr.dl.linux.os": "اوبونتو • دبیان • فدورا • هر توزیع",
      "mnr.dl.linux.desc": "AppImage قابل‌حمل — یک فایل، روی هر توزیع اجرا می‌شود. دانلود → chmod +x → دوبار کلیک یا از هرجا اجرا. بدون نصب root.",
      "mnr.dl.linux.btn1": "دانلود AppImage (x64)",
