      "mnr.dl.mac.desc": "باز کردن .dmg → کشیدن به Applications • شاید در امنیت و حریم خصوصی به «باز کردن به‌هرحال» نیاز باشد",
      "mnr.dl.mac.btn1": "دانلود .dmg برای Apple Silicon",
