      "fw.hero.sub": "Stablecoin white-label e sovrane per il <span class=\"text-[#171717]\">calcolo IA</span>",
      "fw.fund.eyebrow": "FINANZIAMENTO DELLA RISERVA",
      "fw.fund.title": "Avviata da una <span class=\"neon\">note offshore.</span>",
      "fw.fund.desc": "La riserva di ogni coin può essere costituita con note collocate privatamente: una SPV offshore le colloca presso investitori internazionali qualificati, il 100% dei proventi resta in una riserva segregata presso un depositario a copertura del coin, e le note sono servite dai ricavi del calcolo più il rendimento della riserva stessa. I detentori del coin non portano mai il rischio investitore.",
      "fw.fund.notice": "Una struttura, non un'offerta — disponibile su richiesta per investitori istituzionali qualificati.",
      "mnr.nav.daicoin": "Moneta DAI",
