      "mnr.net.eyebrow": "L'INFRASTRUTTURA",
      "mnr.net.title": "Un mesh vivo di<br>fornitori di calcolo.",
      "mnr.net.desc": "I nodi che eseguono LLM locali formano una rete di calcolo IA decentralizzata. Quando arrivano i task, la tua macchina li elabora e guadagna — senza data center.",
      "mnr.app.eyebrow": "L'APP DESKTOP",
      "mnr.app.desc": "Un'unica app nativa. Il tuo nodo entra nella rete, il tuo LLM locale risolve i task IA in arrivo e ogni volta guadagni DAI.",
      "mnr.dl.title": "Pronto a fornire calcolo reale?",
      "mnr.dl.desc": "Scarica il binario precompilato per il tuo sistema. Doppio clic per installare — nessun terminale, nessun codice per utenti non tecnici.",
      "mnr.dl.linux.os": "Ubuntu • Debian • Fedora • Qualsiasi distro",
      "mnr.dl.linux.desc": "AppImage portabile — un solo file, gira su qualsiasi distro. Scarica → chmod +x → doppio clic o avvia da ovunque. Nessuna installazione root.",
