      "fw.hero.sub": "Des stablecoins white-label et souverains pour le <span class=\"text-[#171717]\">calcul IA</span>",
      "fw.fund.eyebrow": "FINANCEMENT DE LA RÉSERVE",
      "fw.fund.title": "Amorcée par une <span class=\"neon\">note offshore.</span>",
      "fw.fund.desc": "La réserve de chaque coin peut être amorcée par des notes placées en privé : une SPV offshore les place auprès d'investisseurs internationaux qualifiés, 100 % des fonds restent dans une réserve cantonnée chez un dépositaire qui adosse le coin, et les notes sont servies par les revenus du calcul plus le rendement de la réserve. Les détenteurs du coin ne portent jamais le risque investisseur.",
      "fw.fund.notice": "Une structure, pas une offre — disponible sur demande pour les investisseurs institutionnels qualifiés.",
      "mnr.nav.daicoin": "Pièce DAI",
      "mnr.hero.title": "Alimentez le cerveau IA.<br><span class=\"neon\">Il gagne quand vous êtes absent.</span>",
      "mnr.hero.cta1": "Lancer un nœud",
      "mnr.hero.cta2": "Voir le mesh en direct",
      "mnr.net.eyebrow": "L'INFRASTRUCTURE",
      "mnr.net.title": "Un mesh vivant de<br>fournisseurs de calcul.",
      "mnr.net.desc": "Des nœuds exécutant des LLM locaux forment un réseau de calcul IA décentralisé. Quand des tâches arrivent, votre machine les traite et gagne — sans data center.",
      "mnr.app.eyebrow": "L'APPLICATION DE BUREAU",
      "mnr.app.desc": "Une seule app native. Votre nœud rejoint le réseau, votre LLM local résout les tâches IA entrantes, et vous gagnez du DAI à chaque fois.",
      "mnr.dl.title": "Prêt à fournir du vrai calcul ?",
      "mnr.dl.desc": "Téléchargez le binaire préconstruit pour votre système. Double-cliquez pour installer — ni terminal ni code pour les utilisateurs non techniques.",
      "mnr.dl.linux.os": "Ubuntu • Debian • Fedora • Toute distro",
      "mnr.dl.linux.desc": "AppImage portable — un seul fichier, tourne sur toute distro. Télécharger → chmod +x → double-cliquer ou lancer depuis n'importe où. Aucune installation root.",
      "mnr.dl.linux.btn1": "Télécharger AppImage (x64)",
      "mnr.dl.linux.btn2": "Télécharger AppImage (ARM64)",
      "mnr.dl.mac.desc": "Ouvrez le .dmg → glissez vers Applications • un « Open Anyway » dans Security & Privacy peut être nécessaire",
      "mnr.dl.mac.btn1": "Télécharger le .dmg Apple Silicon",
      "mnr.dl.mac.btn2": "Télécharger l'installateur .dmg Intel",
      "mnr.dl.win.desc": "Installateur .exe standard avec raccourcis, entrée dans le menu Démarrer et désinstallateur propre. Conçu avec NSIS.",
      "mnr.dl.win.btn": "Télécharger l'installateur Windows",
      "mnr.dl.power.title": "Utilisateurs avancés & installation en une ligne",
      "mnr.dl.power.link1": "Télécharger easy-start.sh",
      "mnr.dl.power.link2": "download-latest.sh (choisit le binaire)",
      "mnr.dl.power.link3": "Voir les scripts de build + le code source",
      "mnr.wal.eyebrow": "APPLICATION COMPAGNON",
      "mnr.wal.title": "Portefeuille DAI Miner",
      "mnr.wal.sub": "Envoyez, recevez et suivez vos récompenses de minage en temps réel — directement depuis votre téléphone.",
      "mnr.wal.f1t": "Solde en direct",
      "mnr.wal.f1d": "Solde en temps réel récupéré depuis votre nœud actif via l'API Wallet légère.",
      "mnr.wal.f2t": "Envoyer & recevoir",
      "mnr.wal.f2d": "Transferts DAI complets entre adresses. Fonctionne avec tout nœud qui connaît le portefeuille.",
      "mnr.wal.f3t": "Historique des transactions",
