      "exp.recenttx": "সাম্প্রতিক লেনদেন",
      "fw.hero.sub": "হোয়াইট-লেবেল, সার্বভৌম <span class=\"text-[#171717]\">AI কম্পিউট</span> স্টেবলকয়েন",
      "fw.fund.eyebrow": "রিজার্ভ তহবিল",
      "fw.fund.title": "সূচনা <span class=\"neon\">অফশোর নোটের মাধ্যমে।</span>",
      "fw.fund.desc": "প্রতিটি কয়েনের রিজার্ভ ব্যক্তিগতভাবে ইস্যু করা নোটের মাধ্যমে গঠন করা যায়: একটি অফশোর SPV সেগুলো যোগ্য আন্তর্জাতিক বিনিয়োগকারীদের কাছে ইস্যু করে, প্রাপ্ত অর্থের 100% কয়েনের সমর্থনকারী একটি পৃথক কাস্টডিয়াল রিজার্ভে থাকে, এবং নোটগুলো পরিশোধ করা হয় কম্পিউট আয় ও রিজার্ভের মুনাফা থেকে। কয়েনধারীরা কখনোই বিনিয়োগকারীর ঝুঁকি বহন করেন না।",
      "fw.fund.notice": "এটি একটি কাঠামো, কোনো প্রস্তাব নয় — অনুরোধে যোগ্য প্রাতিষ্ঠানিক বিনিয়োগকারীদের জন্য উপলব্ধ।",
      "mnr.nav.daicoin": "DAI কয়েন",
      "mnr.hero.title": "AI ব্রেইনকে শক্তি দিন।<br><span class=\"neon\">আপনি বাইরে থাকলেও এটি আয় করে।</span>",
      "mnr.hero.cta1": "নোড চালানো শুরু করুন",
      "mnr.hero.cta2": "লাইভ মেশ দেখুন",
      "mnr.net.eyebrow": "অবকাঠামো",
      "mnr.net.title": "কম্পিউট সরবরাহকারীদের<br>একটি জীবন্ত মেশ।",
      "mnr.net.desc": "স্থানীয় LLM চালানো নোডগুলো মিলে একটি বিকেন্দ্রীভূত AI কম্পিউট নেটওয়ার্ক তৈরি করে। কাজ এলে আপনার মেশিন সেগুলো প্রক্রিয়া করে এবং আয় করে — কোনো ডেটা সেন্টার লাগে না।",
      "mnr.app.eyebrow": "ডেস্কটপ অ্যাপ",
      "mnr.app.desc": "একটি নেটিভ অ্যাপ। আপনার নোড নেটওয়ার্কে যুক্ত হয়, আপনার স্থানীয় LLM আসা AI কাজ সমাধান করে, এবং প্রতিবার আপনি DAI আয় করেন।",
      "mnr.dl.title": "প্রকৃত কম্পিউট দিতে প্রস্তুত?",
      "mnr.dl.desc": "আপনার সিস্টেমের জন্য তৈরি বাইনারি ডাউনলোড করুন। ইনস্টল করতে ডাবল-ক্লিক করুন — অ-কারিগরি ব্যবহারকারীদের জন্য কোনো টার্মিনাল বা কোডিং লাগে না।",
