      "doc.overview.intro": "ہر DAI مائنر <span class=\"neon\">walletApiPort</span> پر (ڈیفالٹ <strong>3456</strong>) ایک HTTP API فراہم کرتا ہے۔ <strong>بیلنس جوابات</strong> <strong>μDAI</strong> میں ہوتے ہیں (raw) — 1 DAI = 1&nbsp;000&nbsp;000&nbsp;000 μDAI۔ <code>/api/wallet/send</code> اور اسٹیکنگ اینڈ پوائنٹس کے لیے <strong>ان پٹ رقوم</strong> <strong>DAI</strong> میں ہوتی ہیں (سرور اندرونی طور پر تبدیل کر لیتا ہے)۔",
