      "doc.gen.title": "والیٹ بنائیں",
      "doc.gen.intro": "DAI والیٹ ایک <strong>ed25519 کی جوڑی</strong> ہے۔ پتہ سائننگ پبلک کی سے اخذ ہوتا ہے — نہ سیڈ فریز، نہ کسٹوڈین۔ والیٹ بنانے اور کام جمع کرانا شروع کرنے کے لیے یہ چار قدم اٹھائیں۔",
      "doc.gen.s1.title": "کی جوڑی بنائیں",
      "doc.gen.s1.desc": "یہ Node.js اسکرپٹ چلائیں (<code>tweetnacl</code> درکار ہے — <code>npm i tweetnacl</code>)۔ یہ 32 بے ترتیب بائٹس سے متعین طور پر ed25519 سائننگ کی جوڑی اخذ کرتا ہے، پھر <code>'dai' + sha256(signingPublicKey).slice(0,40)</code> کے طور پر معیاری DAI پتہ نکالتا ہے۔",
      "doc.gen.s1.note": "<strong class=\"text-[#525252]\"><code>dai-wallet.json</code> کو خفیہ رکھیں۔</strong> <code>signingSecretKeyB64</code> نجی سائننگ کلید ہے — اسے کبھی شیئر یا کمٹ نہ کریں۔",
      "doc.gen.s2.title": "سائننگ کلید چین پر رجسٹر کریں",
      "doc.gen.s2.desc": "قدم 1 سے اپنا پتہ، <code>signingPublicKey</code> اور <code>proof</code> کسی بھی مائنر کو پوسٹ کریں۔ proof آپ کے پتے پر ed25519 دستخط ہے — یہ ثابت کرتا ہے کہ نجی کلید آپ کے پاس ہے۔ اس سے آپ کی کلید آپ کے پتے سے جُڑ جاتی ہے تاکہ نیٹ ورک آپ کے کام کی ادائیگی کے دستخط جانچ سکے۔",
      "doc.gen.s2.errors": "proof نہ ہونے پر <code>400 { \"error\": \"address, signingPublicKey, and proof required\" }</code> ملتا ہے۔ غلط proof پر <code>403 { \"error\": \"invalid proof\" }</code>۔ بعد میں نئی کلید پر جانے کے لیے اپنی <em>موجودہ</em> کلید سے دستخط شدہ <code>rotationProof</code> شامل کریں۔",
      "doc.gen.s2.free": "رجسٹریشن مفت ہے اور فی کی جوڑی صرف ایک بار درکار ہے۔ اس کے لیے کوئی DAI بیلنس ضروری نہیں۔",
      "doc.gen.s3.title": "پتے میں رقم ڈالیں",
