      "doc.jobs.intro": "نیٹ ورک پر کمپیوٹ کام جمع کریں۔ اقسام: <code>verdict</code> (شناختی اسکین، مفت)، <code>skill</code>، <code>compute</code>۔ <code>skill</code> اور <code>compute</code> کاموں کے لیے دستخط شدہ ادائیگی کا ثبوت درکار ہے (<code>maxBudget</code> μDAI میں)۔",
      "doc.jobs.pricing.title": "قیمتیں اور فیس",
      "doc.jobs.pricing.p1": "ادائیگی والے کام ہر AI کمپیوٹ ٹوکن پر <strong>1&nbsp;μDAI&nbsp;فی&nbsp;ٹوکن</strong> کے حساب سے میٹر ہوتے ہیں (ڈیفالٹ <code>gasPrice</code>؛ μDAI سب سے چھوٹی اکائی ہے، سو یہی کم سے کم ہے)۔ چونکہ <strong>1&nbsp;DAI&nbsp;=&nbsp;1&nbsp;000&nbsp;000&nbsp;000&nbsp;μDAI</strong>، ایک DAI سے زیادہ سے زیادہ <strong>1&nbsp;ارب&nbsp;ٹوکن</strong> خریدے جا سکتے ہیں۔",
      "doc.jobs.pricing.p2": "فیس <code>tokensUsed × gasPrice</code> ہے اور یہ <strong>حقیقتاً استعمال شدہ ٹوکنز سے کبھی کم نہیں ہوتی</strong> (1&nbsp;000 ٹوکن ⇒ ≥ 1&nbsp;000&nbsp;μDAI)۔ غیر استعمال شدہ بجٹ واپس کر دیا جاتا ہے۔ ایسا <code>maxBudget</code> جو کام کی ٹوکن لاگت پوری نہ کر سکے، <code>402 FEE_TOO_LOW</code> کے ساتھ مسترد ہو جاتا ہے۔",
      "doc.jobs.pricing.p3": "<strong>بلاک انعام۔</strong> فیس کے علاوہ، ہر بلاک کی ~1&nbsp;DAI سبسڈی <strong>ان ورکرز میں تقسیم ہوتی ہے جنہوں نے کام مکمل کیے، فراہم کردہ کمپیوٹ کے تناسب سے</strong> (ایک متعین ٹوکن تخمینہ — کئی نوڈز میں بانٹنے سے کچھ اضافی نہیں ملتا)، اس میں سے تھوڑا (~10%) پروپوزر حصہ نکل جاتا ہے۔ جن بلاکس میں حقیقی کام نہ ہو وہ صرف معمولی کیپ الائیو بناتے ہیں، سو اجرا طلب کے مطابق چلتا ہے۔",
      "doc.jobs.pricing.p4": "DAI کی کوئی مقررہ قیمت نہیں — منڈی بہترین کھلے P2P آرڈر کے ذریعے اسے طے کرتی ہے (دیکھیں <code>GET /api/p2p/price</code>)۔",
      "doc.jobs.submit": "کام جمع کریں۔ <code>{ jobId, statusUrl, resultUrl }</code> واپس کرتا ہے۔ <code>id</code> <em>کلائنٹ</em> بناتا ہے اور یہ ادائیگی کے ثبوت میں دستخط ہوتا ہے: <code>paymentTx.txHash</code> <code>JSON.stringify({ jobId, requesterAddress, minerAddress, amount, nonce })</code> کا SHA-256 ہے — کوئی بلاک چین لین دین ہیش نہیں۔ <code>minerAddress</code> <code>GET /api/miner/info</code> سے آتا ہے؛ <code>nonce</code> والیٹ کی <em>موجودہ</em> <code>/api/wallet/nonce</code> قدر ہے؛ دستخط ہیکس ہیش سٹرنگ پر ہوتا ہے۔ اسٹیبل کوائن میں ادائیگی کرتے وقت ہیش کیے گئے آبجیکٹ میں <code>currency</code> شامل کریں۔",
