      "fw.hero.sub": "Stablecoins de <span class=\"text-[#171717]\">computação de IA</span> soberanas e white-label",
      "fw.fund.eyebrow": "FINANCIAMENTO DA RESERVA",
      "fw.fund.title": "Iniciada por uma <span class=\"neon\">nota offshore.</span>",
      "fw.fund.desc": "A reserva de cada moeda pode ser formada com notas de colocação privada: uma SPV offshore as coloca junto a investidores internacionais qualificados, 100% dos recursos ficam em uma reserva custodial segregada que lastreia a moeda, e as notas são remuneradas pela receita de computação mais o rendimento da reserva. Os detentores da moeda nunca assumem o risco do investidor.",
