      "mnr.net.desc": "Nós que rodam LLMs locais formam uma rede descentralizada de computação de IA. Quando as tarefas chegam, sua máquina as processa e ganha — sem precisar de data center.",
      "mnr.app.eyebrow": "O APP DE DESKTOP",
