      "b2b.hero.sub": "ཁྱོད་ཀྱིས་ལག་ལེན་འཐབ་མི་ AI འདི་ཁྱོད་རང་གིས་སྐྱོང་ཨིན། འདི་གིས་ག་ཅི་འབད་ནི་ཨིན་ན་ཚོགས་རྒྱབ། ཐག་གཅད་ནི་ལུ་ཤུགས་རྐྱབ་ནི་འདི་ལས་རིམ་གྱི་གནས་རིམ་ལུ་ཨིན། ཚོང་སྡེ་ཅིག་བརྒྱུད་དེ་མེན།",
      "b2b.hero.cta1": "གཏེར་སྐྲུན་གཡོག་བཀོལ། →",
      "b2b.hero.cta2": "ག་དེ་སྦེ་ལཱ་འབདཝ་ཨིན་ན།",
      "b2b.trust.eyebrow": "སྒོ་སྲུང་མེན་ གཞི་སྐྱོང་ཨིན།",
      "b2b.trust.title": "AI གིས་ག་ཅི་འབད་ནི་ཨིན་ན་ཁྱོད་ཀྱིས་གཏན་འཁེལ་བཟོཝ་ཨིན།",
      "b2b.trust.1t": "ཐག་གཅད་ལུ་ཤུགས།",
      "b2b.trust.1d": "མཚམས་རེ་རེ་ལུ་སྐད་ཡོད། དྲ་བ་གིས་ག་ཅི་གཡོག་བཀོལ་ནི་ཨིན་ན་ — དཔེ་གཞི། རིག་རྩལ། དེ་ལས་སྒྲིག་གཞི་ — ལས་རིམ་བརྒྱུད་དེ་བཟོ། ཚོགས་ཁང་ནང་མེན།",
      "b2b.trust.2t": "བཀོད་སྒྲིག་ལས་དབུས་མེད།",
      "b2b.trust.2d": "རང་དབང་ཅན་གྱི་མཚམས་ཚུ། གཅིག་ལས་གཅིག། དྲ་བ་འདི་ཚོང་སྡེ་ག་གིས་ཡང་བདག་འཛིན་མི་འབད། བཀག་ནིའི་ལྟེ་བའི་མཐེབ་གཅུ་ཡང་མེད།",
      "b2b.trust.3t": "རང་དབང་གི་ཚད་འཛིན།",
      "b2b.trust.3d": "དཔེ་གཞི། རིག་རྩལ། དེ་ལས་གནས་སྡུད་ཚུ་ཁྱོད་ཀྱིས་གདམ་ཁ་རྐྱབ་ཨིན། ལྡེ་མིག་ཚུ་ཁྱོད་ལུ་སྡོདཔ་ཨིན། གནས་སྟངས་ཁྱོད་ཀྱིས་བཟོཝ་ཨིན།",
      "b2b.trust.4t": "ཁྱོད་ཀྱི་ཞབས་ཏོག་ལས་ཐོབ།",
      "b2b.trust.4d": "མཇུག་བསྡུ་ཡོད་པའི་ལས་ཀ་རེ་རེ་གིས་ འདི་འགྲུབ་བཅུག་མི་མཚམས་ཚུ་ལུ་སྤྲོདཔ་ཨིན། ཁྱོད་ཀྱི་གཞི་རྟེན་མཁོ་ཆས་འདི་རྒྱུ་ནོར་ཅིག་ལུ་འགྱུརཝ་ཨིན།",
      "b2b.build.eyebrow": "བཟོ་སྐྲུན་པ་ཚུ་གི་དོན་ལུ།",
      "b2b.build.title": "ཁྱོད་ཀྱི་ཐོན་སྐྱེད་ལུ་དགོ་མི་གཡོག་བཀོལ།",
      "b2b.build.1t": "ཁྱོད་རང་གི་དཔེ་གཞི།",
      "b2b.build.1d": "ཁྱོད་རང་གི་ LLM འབག་ཤོག་ ཡང་ན་ལས་ཀ་རེ་ལུ་གདམ་ཁ་རྐྱབ། སྒེར་གྱི་གནས་སྡུད་ཚུ་སྦྱར་ ཡང་ན་ Hugging Face ལས་འཐེན། ཁྱོད་ཀྱིས་ག་ཏེ་སླབ་མི་ནང་དྲ་བ་གིས་གཡོག་བཀོལ་ཨིན།",
      "b2b.build.2t": "འཐུས་མི་དང་རིག་རྩལ།",
      "b2b.build.2d": "ཁྱོད་ཀྱི་གནས་སྡུད། གནས་སྡུད་ཚོགས། དེ་ལས་ཤེས་ཡོན་ཚུ་བཞག། MCP བརྒྱུད་དེ་ལག་ཆས་ཚུ་མཐུད། ཁྱོད་ཀྱི་མ་དཔེ་ཚུ་གིས་ག་ཅི་མཐོང་ནི་ཨིན་ན་ཁྱོད་ཀྱིས་གཏན་འཁེལ་བཟོཝ་ཨིན།",
      "b2b.build.3t": "འཇམ་ཏོང་ཏོང་གི་ API གཅིག།",
      "b2b.build.3d": "ག་ར་ HTTP API གཅིག་ཨིན། — ལས་ཀ། ཁ་བརྡ། འཚོལ་ཞིབ། སྤྲོད་ལེན། ཕྱི་རུ་གཅིག་ནང་མཉམ་སྦྱོར་འབད།",
      "b2b.build.3cta": "API ཡིག་ཆ་ལྷག →",
      "b2b.build.4t": "ཊོ་ཀཱན་རེ་ལུ་སྤྲོད།",
      "b2b.build.4d": "AI རྩིས་སྒྲུབ་ཀྱི་ཊོ་ཀཱན་རེ་རེ་བཞིན་དུ་ཚད་འཇལ་ཨིན། ལས་ཀ་རེ་ལུ་མ་དངུལ་གྱི་ཚད་ངེས་ཅན་ཡོད། མ་ལག་ལེན་འཐབ་པའི་མ་དངུལ་ཕྱིར་སློག་འབདཝ་ཨིན། ཁྱོད་ཀྱི་རྩིས་ཐོ་ནང་ལཱ་མེད་པའི་ GPU མེད།",
      "b2b.how.eyebrow": "ག་དེ་སྦེ་ལཱ་འབདཝ་ཨིན་ན།",
      "b2b.how.title": "གཅིག་ལས་གཅིག། མར་ལས་ཡར།",
      "b2b.how.1t": "ལས་ཀ་ཞུ།",
      "b2b.how.1d": "ཁྱོད་ཀྱི་མ་དངུལ་དང་དགོ་མི་ — དཔེ་གཞི། རིག་རྩལ། ཡང་ན་གཉིས་ཆ་ར་ — བཤད་དེ་དྲ་བ་ལུ་ལས་ཀ་ཅིག་བཀོད།",
      "b2b.how.2t": "མཚམས་ཚུ་འགྲན་བསྡུར་འབདཝ་ཨིན།",
      "b2b.how.2d": "མཐུན་པའི་རིག་རྩལ་ཡོད་པའི་རང་དབང་ཅན་གྱི་མཚམས་ཚུ་གིས་གོང་ཚད་བཀོད་དེ་ལཱ་འབདཝ་ཨིན། མགྱོགས་ཤོས་ཀྱིས་རྒྱལ་ཁ་ཐོབ་ཨིན། ཁྱོད་ཀྱིས་ལག་ལེན་འཐབ་མི་རྐྱངམ་གཅིག་སྤྲོདཔ་ཨིན།",
      "b2b.how.3t": "ཅིང་གུ་གཏན་འཁེལ།",
      "b2b.how.3d": "ལས་ཀ་འདི་ཅིང་གུ་ངེས་བདེན་བཟོཝ་ཨིན། མཚམས་ཚུ་ལུ་ཐད་ཀར་སྤྲོདཔ་ཨིན། བར་མི་མེད། ཡོངས་རྫོགས་གསལ་ཏོང་ཏོང་།",
      "b2b.ent.eyebrow": "ཚོང་སྡེ།",
      "b2b.ent.title": "ཚད་ཆེ་བ་<br><span class=\"neon\">ཡང་ན་ SLA དགོཔ་ཨིན་ན།</span>",
      "b2b.ent.desc": "ཐོན་སྐྱེད་ཀྱི་ལཱ་གི་དོན་ལུ་དམིགས་བསལ་གྱི་ནུས་ཤུགས། སྒེར་གྱི་ཚོགས་ཁག། དེ་ལས་བོངས་ཚད་ཀྱི་རིན་གོང་། ཁྱོད་ཀྱིས་ EUR, USD ཡང་ན་ USDT ནང་སྤྲོདཔ་ཨིན། — གཞུང་འབྲེལ་དང་ཡོངས་རྫོགས་རྩིས་ཐོ་དང་བཅས། དྲ་བ་གཡོག་བཀོལ་མི་མི་སྡེ་ལུ་ས་གནས་ཀྱི་བརྟན་དངུལ་ནང་སྤྲོདཔ་ཨིན།",
      "b2b.ent.cta": "ང་བཅས་དང་གྲོས་བསྟུན་འབད། — རིན་གོང་ངེས་ཅན་ལེན། →",
