      "exp.search.ph": "ཁ་བྱང་། tx ཧེཤ། ཡང་ན་བློཀ་གི་མཐོ་ཚད་ཀྱིས་འཚོལ…",
      "exp.search.btn": "འཚོལ།",
      "exp.search.hint": "བརྡ་དོན། ལྷག་ལུས། སྤོ་བཤུད། དེ་ལས་ལས་ཀ་ཚུ་བལྟ་ནིའི་དོན་ལུ་ <span class=\"mono\">dai…</span> ཁ་བྱང་ཅིག་སྦྱར།",
      "exp.tab.blocks": "བློཀ།",
