      "exp.jobs": "མཇུག་བསྡུ་ཡོད་པའི་ལས་ཀ།",
      "exp.recenttx": "ཉེ་ཆར་གྱི་སྤོ་བཤུད།",
      "fw.hero.sub": "ཝའིཊ་ལེབཱལ། རང་དབང་ཅན་གྱི་ <span class=\"text-[#171717]\">AI རྩིས་སྒྲུབ་</span>བརྟན་དངུལ།",
      "fw.fund.eyebrow": "ཉར་ཚགས་མ་དངུལ།",
      "fw.fund.title": "<span class=\"neon\">རྒྱ་མཚོའི་ཕྱི་ཁའི་ནོཊི་</span>གིས་འགོ་བཙུགས།",
      "fw.fund.desc": "དངུལ་སྒོར་རེ་རེའི་ཉར་ཚགས་འདི་སྒེར་གྱིས་བཀོད་པའི་ནོཊི་གིས་འགོ་བཙུགས་ཚུགས། རྒྱ་མཚོའི་ཕྱི་ཁའི་ SPV གིས་དེ་ཚུ་ཚད་ལྡན་རྒྱལ་སྤྱིའི་མ་རྩ་གཏོང་མི་ཚུ་ལུ་བཀོདཔ་ཨིན། ཐོབ་པའི་དངུལ་གྱི་བརྒྱ་ཆ་ 100 འདི་དངུལ་སྒོར་ལུ་རྒྱབ་སྐྱོར་འབད་མི་ལོགས་སུ་བའི་ཉར་ཚགས་ནང་བཞག་ཨིན། ནོཊི་ཚུ་རྩིས་སྒྲུབ་ཀྱི་འོང་འབབ་དང་ཉར་ཚགས་ཀྱི་ཁེ་བཟང་གིས་སྤྲོདཔ་ཨིན། དངུལ་སྒོར་འཆང་མི་ཚུ་གིས་མ་རྩ་གཏོང་མིའི་ཉེན་ཁ་ནམ་ཡང་མི་འབག།",
      "fw.fund.notice": "འདི་བཀོད་སྒྲིག་ཅིག་ཨིན་ གོ་སྐབས་ཅིག་མེན། ཞུ་བ་དང་འཁྲིལ་ཏེ་ཚད་ལྡན་གཞི་ཚོགས་ཀྱི་མ་རྩ་གཏོང་མི་ཚུ་ལུ་འཐོབ་ཚུགས།",
      "mnr.nav.daicoin": "DAI དངུལ་སྒོར།",
      "mnr.hero.title": "AI ཀློད་པ་ལུ་ནུས་ཤུགས་བྱིན།<br><span class=\"neon\">ཁྱོད་ཕྱི་ཁར་ཡོད་པའི་སྐབས་ཡང་ཐོབཔ་ཨིན།</span>",
      "mnr.hero.cta1": "མཚམས་གཡོག་བཀོལ་འགོ་བཙུགས།",
      "mnr.hero.cta2": "ཐད་ཀར་དྲ་བ་བལྟ།",
      "mnr.net.eyebrow": "གཞི་རྟེན་མཁོ་ཆས།",
      "mnr.net.title": "རྩིས་སྒྲུབ་བྱིན་མི་ཚུ་གི་<br>གསོན་པོའི་དྲ་བ།",
      "mnr.net.desc": "ས་གནས་ཀྱི་ LLM གཡོག་བཀོལ་མི་མཚམས་ཚུ་གིས་དབུས་མེད་ AI རྩིས་སྒྲུབ་ཀྱི་དྲ་བ་ཅིག་གྲུབ་ཨིན། ལས་ཀ་འོང་པའི་སྐབས་ ཁྱོད་ཀྱི་གློག་རིག་གིས་དེ་ཚུ་ལས་སྦྱོར་འབད་ཞིནམ་ལས་ཐོབཔ་ཨིན། གནས་སྡུད་ལྟེ་བ་མི་དགོ།",
      "mnr.app.eyebrow": "ཌེཀསི་ཊོབ་གློག་རིམ།",
